import{DERBY_CONFIG as s}from"./config.min.js";export function fitDistance(e,i,r){const t=i*Math.PI/360,n=Math.atan(Math.tan(t)*r);return e/Math.tan(n)}function c(e,i,r){const t=Math.hypot(e,i,r)||1;return{x:e/t,y:i/t,z:r/t}}export const SHOTS=Object.freeze({start:Object.freeze({dir:c(.85,-.05,.55),minDistance:.75,halfWidth:.28,lift:.02}),chase:Object.freeze({dir:c(-.9,.6,.42),minDistance:.95,halfWidth:.3,ahead:.35}),finish:Object.freeze({dir:c(.6,.42,.5),minDistance:.85,halfWidth:.3,ahead:-.3}),photo:Object.freeze({dir:c(.1,1,.03),minDistance:.45,halfWidth:.26,ahead:0})});export function shotFor(e,i,{reducedMotion:r=!1}={},t=s){return e==="staging"||e==="gate"?"start":e==="replay"?"photo":e==="times"||r||i>=t.track.courseLength-t.camera.finishFrom?"finish":"chase"}export function framing(e,i,r,t,n=s){const a=SHOTS[e]||SHOTS.finish;let h;e==="start"?h=i.at(0):e==="chase"?h=i.at(r+a.ahead):h=i.at(n.track.courseLength+a.ahead);const f={x:h.x,y:h.y+(a.lift||.01),z:0},o=Math.max(a.minDistance,fitDistance(a.halfWidth,n.camera.fov,t));return{target:f,position:{x:f.x+a.dir.x*o,y:f.y+a.dir.y*o,z:f.z+a.dir.z*o}}}export const CROWD_SHOT=Object.freeze({dir:c(-.22,.1,1),height:1,halfWidth:1.3,minDistance:3.2});export function crowdFraming(e,i,r=s){const t=CROWD_SHOT,n={x:e.x,y:t.height,z:e.z-.3},a=Math.max(t.minDistance,fitDistance(t.halfWidth,r.camera.fov,i));return{target:n,position:{x:n.x+t.dir.x*a,y:n.y+t.dir.y*a,z:n.z+t.dir.z*a}}}
